glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec3 add = vec3(0.0);
  for (int i = 0; i < 18; i++) {
    float fi = float(i);
    vec2 p = vec2(noise(vec2(fi * 3.1, uTime * 0.3)), noise(vec2(fi * 7.7, uTime * 0.25 + 9.0)));
    vec2 d = (uv - p) * vec2(uRatio, 1.0);
    float tw = 0.6 + 0.4 * sin(uTime * 3.0 + fi);
    add += vec3(1.0, 0.85, 0.35) * exp(-length(d) * 70.0) * 1.8 * tw;
  }
  return vec4(c.rgb + add * uAmount, c.a);
}
